"notes": "Главное правило — после яиц суп больше не кипит, иначе будет яичный суп с хлопьями. Разогревать завтра тоже аккуратно, на слабом огне.",
"tips": [
[
"Чихиртма или авголемоно",
"С чихиртмой роднит одно: обе заправляются яйцом, введённым в горячий бульон. Дальше расходятся. Авголемоно: кислота от лимона (много), загуститель — только яйца и крахмал из риса/орзо, без муки, без лука в заправке, без специй; на выходе светлый, лимонный, «чистый» вкус. Чихиртма: кислота от уксуса, лук, томлённый с маслом и мукой, сухая мята или кинза, на выходе плотнее, луковее, «теплее»."
]
]
