"note": "Как чистить: разморозить в холодильнике за ночь или в пакете в миске холодной воды (20–30 минут). Голову — открутить, держа креветку за тело. Панцирь — снимать с брюшка, где лапки: подцепить пальцем, он сходит кольцами; хвостик можно оставить для красоты. Ножом сделать неглубокий надрез вдоль спинки и вытащить тёмную кишку, если она видна. Головы и панцири — сразу в зип-пакет: если не варишь бульон сегодня, в морозилку (до 2 месяцев), туда же можно докладывать следующие. 500 г целых креветок — это ~250 г мяса и ~250 г голов и панцирей. Целые обычно дешевле за кило мяса и вкуснее. После «Приготовлено» головы окажутся на складе, а 🔍 у них покажет, что из них сварить: бульон, биск или чили-кранч.",
